import{_ as r,o as a,c as t,ah as s}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Rémunérations","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/remunerations.md","filePath":"src/guide/coordinateur/remunerations.md"}'),n={name:"guide/coordinateur/remunerations.md"};function o(i,e,u,l,c,d){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="remunerations" tabindex="-1">Rémunérations <a class="header-anchor" href="#remunerations" aria-label="Permalink to &quot;Rémunérations&quot;">​</a></h1><p>Les sommes dues aux formateurs, aux coachs, aux jurés se préparent dans <strong>Finance</strong>. Kura calcule ou enregistre, <strong>vous validez</strong>, puis vous <strong>enregistrez le versement fait hors de Kura</strong> : Kura n&#39;exécute aucun virement.</p><h2 id="formateurs-coachs-et-jury" tabindex="-1">Formateurs, coachs et jury <a class="header-anchor" href="#formateurs-coachs-et-jury" aria-label="Permalink to &quot;Formateurs, coachs et jury&quot;">​</a></h2><p><strong>Finance → Rémunérations</strong> liste les lignes de chaque bénéficiaire, par cohorte et par nature : heures de formation, forfait projet, coaching, jeton de jury.</p><h3 id="la-grille-de-remuneration" tabindex="-1">La grille de rémunération <a class="header-anchor" href="#la-grille-de-remuneration" aria-label="Permalink to &quot;La grille de rémunération&quot;">​</a></h3><p>Depuis la page, la <strong>grille de rémunération</strong> donne les taux en vigueur : taux horaire par zone de rentabilité, forfait projet par cohorte, forfait coaching par apprenant au démarrage, jeton de jury par juré et par date de soutenance. <strong>Programmer un taux</strong> le fait prendre effet à une date. Une cohorte garde les taux en vigueur <strong>à son démarrage</strong>.</p><h3 id="calculer" tabindex="-1">Calculer <a class="header-anchor" href="#calculer" aria-label="Permalink to &quot;Calculer&quot;">​</a></h3><p>À la fin d&#39;une cohorte, Kura calcule :</p><ul><li><strong>heures de formation</strong> : heures du programme × taux de la <strong>zone au démarrage</strong> ;</li><li><strong>forfait projet</strong> ;</li><li><strong>coaching</strong> : effectif au démarrage × forfait par apprenant.</li></ul><p>Si plusieurs formateurs (ou plusieurs coachs) se partagent la cohorte, la somme est <strong>partagée à parts égales</strong>. L&#39;effectif et la zone retenus sont ceux du <strong>démarrage</strong>, même si un apprenant abandonne ensuite.</p><p>Si un taux manquait à la clôture, la cohorte apparaît dans <strong>Cohortes terminées à calculer</strong> avec les taux manquants : complétez la grille, puis <strong>Calculer</strong>.</p><p>Les <strong>jetons de jury</strong> sont dus à chaque juré enregistré (voir <a href="./resultats.html#les-membres-du-jury">Résultats et certification</a>) une fois la date de soutenance passée.</p><h3 id="ajuster-valider-verser" tabindex="-1">Ajuster, valider, verser <a class="header-anchor" href="#ajuster-valider-verser" aria-label="Permalink to &quot;Ajuster, valider, verser&quot;">​</a></h3><ol><li><strong>Ajuster</strong> une ligne si besoin : le montant calculé reste visible, l&#39;ajustement est journalisé.</li><li>Sélectionnez des lignes et <strong>validez-les</strong>.</li><li>Quand le versement est fait, <strong>enregistrez-le</strong> : les lignes validées sont soldées.</li></ol><p>Chaque bénéficiaire suit ses lignes dans <strong>Ma rémunération</strong>.</p><p>Les commissions des apporteurs d&#39;affaires et des partenaires marketing ne se gèrent plus dans Kura : elles sont suivies dans Naia.</p>',16)])])}const p=r(n,[["render",o]]);export{m as __pageData,p as default};
